     8	/** Configuração da instalação, lida das variáveis de ambiente. */
     9	public record Config(
    10	        int port, String dbUrl, String dbUser, String dbPassword,
    11	        boolean testMode, ZoneId zone, Notifications notifications) {
    12	
    13	    /** Em que modo uma regra de mensagem vale. */
    14	    public enum Scope {
    15	        ALWAYS, TEST_ONLY, LIVE_ONLY, NEVER;
    16	
    17	        public boolean appliesTo(boolean testMode) {
    18	            return switch (this) {
    19	                case ALWAYS -> true;
    20	                case TEST_ONLY -> testMode;
    21	                case LIVE_ONLY -> !testMode;
    22	                case NEVER -> false;
    23	            };
    24	        }
    25	    }
    26	
    27	    /** Regras das mensagens enviadas; cada instalação escolhe a sua combinação. */
    28	    public record Notifications(
    29	            Scope addressValidation, Scope archiveCopy, Scope quietHours, Scope dailyLimit,
    30	            String archiveAddress, String testAddress,
    31	            LocalTime quietStart, LocalTime quietEnd, int maxPerGuestPerDay) {
    32	
    33	        public static Notifications defaults() {
    34	            return new Notifications(Scope.ALWAYS, Scope.LIVE_ONLY, Scope.NEVER, Scope.NEVER,
    35	                    "arquivo@pousadamarealta.com.br", "testes@pousadamarealta.com.br",
    36	                    LocalTime.of(22, 0), LocalTime.of(7, 0), 5);
    37	        }
    38	    }
    39	
    40	    public static Config fromEnv(Map<String, String> env) {
    41	        Notifications d = Notifications.defaults();
    42	        Notifications n = new Notifications(
    43	                scope(env, "HOTEL_RULE_ADDRESS_VALIDATION", d.addressValidation()),
    44	                scope(env, "HOTEL_RULE_ARCHIVE_COPY", d.archiveCopy()),
    45	                scope(env, "HOTEL_RULE_QUIET_HOURS", d.quietHours()),
    46	                scope(env, "HOTEL_RULE_DAILY_LIMIT", d.dailyLimit()),
    47	                text(env, "HOTEL_ARCHIVE_ADDRESS", d.archiveAddress()),
    48	                text(env, "HOTEL_TEST_ADDRESS", d.testAddress()),
    49	                time(env, "HOTEL_QUIET_HOURS_START", d.quietStart()),
    50	                time(env, "HOTEL_QUIET_HOURS_END", d.quietEnd()),
    51	                Integer.parseInt(text(env, "HOTEL_DAILY_LIMIT", String.valueOf(d.maxPerGuestPerDay()))));
    52	        return new Config(
    53	                Integer.parseInt(text(env, "PORT", "7070")),
    54	                env.get("DB_URL"), env.get("DB_USER"), env.get("DB_PASSWORD"),
    55	                "true".equalsIgnoreCase(text(env, "HOTEL_TEST_MODE", "false")),
    56	                ZoneId.of(text(env, "HOTEL_ZONE", "America/Sao_Paulo")),
    57	                n);
    58	    }
    59	
    60	    private static String text(Map<String, String> env, String key, String def) {
    61	        String v = env.get(key);
    62	        return v == null || v.isBlank() ? def : v.trim();
    63	    }
    64	
    65	    private static Scope scope(Map<String, String> env, String key, Scope def) {
    66	        return Scope.valueOf(text(env, key, def.name()).toUpperCase(Locale.ROOT));
    67	    }
    68	
    69	    private static LocalTime time(Map<String, String> env, String key, LocalTime def) {
    70	        return LocalTime.parse(text(env, key, def.toString()));
    71	    }
    72	}
