    92	              check_in DATE NOT NULL,
    93	              check_out DATE NOT NULL,
    94	              guests INTEGER NOT NULL,
    95	              rate_plan VARCHAR(20) NOT NULL,
    96	              nights INTEGER NOT NULL,
    97	              subtotal NUMERIC(14,2) NOT NULL,
    98	              discount NUMERIC(14,2) NOT NULL,
    99	              total NUMERIC(14,2) NOT NULL,
   100	              status VARCHAR(20) NOT NULL,
   101	              amount_paid NUMERIC(14,2) NOT NULL DEFAULT 0,
   102	              refund NUMERIC(14,2)
   103	            );
   104	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in, check_out);
   105	            CREATE INDEX IF NOT EXISTS reservations_check_in_idx ON reservations (check_in);
   106	            CREATE TABLE IF NOT EXISTS messages (
