    27	public final class Main {
    28	    private static final Logger log = LoggerFactory.getLogger(Main.class);
    29	    private static final ObjectMapper JSON = new ObjectMapper()
    30	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
    31	            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
