    94	                v.put("to", m.to());
    95	                v.put("subject", m.subject());
    96	                v.put("body", m.body());
    97	                v.put("status", m.status());
    98	                out.add(v);
    99	            }
   100	            json(ctx, 200, out);
   101	        });
   102	
   103	        app.get("/reports/occupancy", ctx -> {
   104	            String d = ctx.queryParam("date");
   105	            if (d == null || !DAY.matcher(d).matches()) throw ApiException.invalid("Informe date no formato AAAA-MM-DD");
   106	            csv(ctx, service.occupancyCsv(date(d, "date")));
   107	        });
