612	    11	/**
613	    12	 * Regras das mensagens enviadas. Uma mensagem entra como rascunho, passa por uma cadeia de regras
614	    13	 * e sai como uma ou mais mensagens (a original, uma possível cópia para o arquivo), enviadas ou bloqueadas.
615	    14	 *
616	    15	 * O redirecionamento do modo de teste é sempre a última etapa e age sobre todas as mensagens
617	    16	 * que vão sair, para que nada chegue a um endereço real nesse modo.
618	    17	 */
619	    18	public final class Messaging {
620	    19	    private Messaging() {}
