622	    21	    public enum Channel { EMAIL }
623	    22	
624	    23	    public enum MessageStatus { SENT, BLOCKED }
625	    24	
626	    25	    public record Draft(String to, String subject, String body) {}
627	    26	
628	    27	    /**
629	    28	     * @param guestAddress endereço original do hóspede (para contar o limite diário)
630	    29	     * @param copy true se for a cópia para o arquivo
631	    30	     */
632	    31	    public record Outgoing(
633	    32	            Channel channel, String to, String subject, String body, MessageStatus status,
634	    33	            String guestAddress, boolean copy) {
635	    34	
636	    35	        boolean sent() {
637	    36	            return status == MessageStatus.SENT;
638	    37	        }
639	    38	    }
640	    39	
641	    40	    /** O que as regras precisam saber do momento do envio. */
642	    41	    public record Context(boolean testMode, ZonedDateTime now, ToIntFunction<String> sentTodayTo) {}
643	    42	
644	    43	    public interface Rule {
645	    44	        void apply(List<Outgoing> messages, Context ctx);
646	    45	    }
