648	    47	    public static boolean isValidAddress(String a) {
649	    48	        if (a == null || a.isEmpty() || a.chars().anyMatch(Character::isWhitespace)) {
650	    49	            return false;
651	    50	        }
652	    51	        int at = a.indexOf('@');
653	    52	        if (at <= 0 || at != a.lastIndexOf('@')) {
654	    53	            return false;
655	    54	        }
656	    55	        String[] labels = a.substring(at + 1).split("\\.", -1);
657	    56	        if (labels.length < 2) {
658	    57	            return false;
659	    58	        }
660	    59	        for (String l : labels) {
661	    60	            if (l.isEmpty()) {
662	    61	                return false;
663	    62	            }
664	    63	        }
665	    64	        return true;
666	    65	    }
