668	    67	    public static final class Pipeline {
669	    68	        private final List<Rule> rules = new ArrayList<>();
670	    69	
671	    70	        public Pipeline(Notifications n, boolean testMode) {
672	    71	            if (n.addressValidation().appliesTo(testMode)) {
673	    72	                rules.add(blockWhen((m, c) -> !isValidAddress(m.to())));
674	    73	            }
675	    74	            if (n.quietHours().appliesTo(testMode)) {
676	    75	                rules.add(blockWhen((m, c) -> inQuietHours(c.now().toLocalTime(), n.quietStart(), n.quietEnd())));
677	    76	            }
678	    77	            if (n.dailyLimit().appliesTo(testMode)) {
679	    78	                rules.add(blockWhen((m, c) -> c.sentTodayTo().applyAsInt(m.guestAddress()) >= n.maxPerGuestPerDay()));
680	    79	            }
681	    80	            if (n.archiveCopy().appliesTo(testMode)) {
682	    81	                rules.add(archiveCopy(n.archiveAddress()));
683	    82	            }
684	    83	            if (testMode) {
685	    84	                rules.add(testRedirect(n.testAddress()));
686	    85	            }
687	    86	        }
688	    87	
689	    88	        public List<Outgoing> process(Draft draft, Context ctx) {
690	    89	            List<Outgoing> out = new ArrayList<>();
691	    90	            out.add(new Outgoing(Channel.EMAIL, draft.to(), draft.subject(), draft.body(),
692	    91	                    MessageStatus.SENT, draft.to(), false));
693	    92	            for (Rule r : rules) {
694	    93	                r.apply(out, ctx);
695	    94	            }
696	    95	            return out;
697	    96	        }
698	    97	    }
