700	    99	    interface Condition {
701	   100	        boolean test(Outgoing m, Context c);
702	   101	    }
703	   102	
704	   103	    static boolean inQuietHours(LocalTime t, LocalTime start, LocalTime end) {
705	   104	        if (start.equals(end)) {
706	   105	            return false;
707	   106	        }
708	   107	        return start.isBefore(end)
709	   108	                ? !t.isBefore(start) && t.isBefore(end)
710	   109	                : !t.isBefore(start) || t.isBefore(end);
711	   110	    }
712	   111	
713	   112	    /** Bloqueia a mensagem original; o endereço fica como estava. */
714	   113	    private static Rule blockWhen(Condition cond) {
715	   114	        return (messages, ctx) -> {
716	   115	            for (int i = 0; i < messages.size(); i++) {
717	   116	                Outgoing m = messages.get(i);
718	   117	                if (m.sent() && !m.copy() && cond.test(m, ctx)) {
719	   118	                    messages.set(i, new Outgoing(m.channel(), m.to(), m.subject(), m.body(),
720	   119	                            MessageStatus.BLOCKED, m.guestAddress(), false));
721	   120	                }
722	   121	            }
723	   122	        };
724	   123	    }
