726	   125	    private static Rule archiveCopy(String archive) {
727	   126	        return (messages, ctx) -> {
728	   127	            for (int i = 0; i < messages.size(); i++) {
729	   128	                Outgoing m = messages.get(i);
730	   129	                if (m.sent() && !m.copy()) {
731	   130	                    messages.add(i + 1, new Outgoing(m.channel(), archive, "[Cópia] " + m.subject(),
732	   131	                            m.body(), MessageStatus.SENT, m.guestAddress(), true));
733	   132	                    i++;
734	   133	                }
735	   134	            }
736	   135	        };
737	   136	    }
738	   137	
739	   138	    private static Rule testRedirect(String testAddress) {
740	   139	        return (messages, ctx) -> {
741	   140	            for (int i = 0; i < messages.size(); i++) {
742	   141	                Outgoing m = messages.get(i);
743	   142	                if (m.sent()) {
744	   143	                    messages.set(i, new Outgoing(m.channel(), testAddress, "[TESTE] " + m.subject(),
745	   144	                            "Destinatário original: " + m.to() + "\n" + m.body(),
746	   145	                            MessageStatus.SENT, m.guestAddress(), m.copy()));
747	   146	                }
748	   147	            }
749	   148	        };
750	   149	    }
