775	    19	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
776	    20	    public static boolean isPeakSeason(LocalDate night) {
777	    21	        Month m = night.getMonth();
778	    22	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
779	    23	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
780	    24	    }
