782	    26	    public static BigDecimal nightPrice(Room room, LocalDate night) {
783	    27	        BigDecimal rate = room.nightlyRate();
784	    28	        if (isPeakSeason(night)) {
785	    29	            rate = rate.multiply(PEAK_FACTOR);
786	    30	        }
787	    31	        return money(rate);
788	    32	    }
789	    33	
790	    34	    /** As noites são as datas de checkIn (inclusive) a checkOut (exclusive). */
791	    35	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
792	    36	        BigDecimal subtotal = BigDecimal.ZERO.setScale(2);
793	    37	        int nights = 0;
794	    38	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
795	    39	            subtotal = subtotal.add(nightPrice(room, d));
796	    40	            nights++;
797	    41	        }
798	    42	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
799	    43	                ? money(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
800	    44	                : money(BigDecimal.ZERO);
801	    45	        return new Quote(nights, subtotal, discount, money(subtotal.subtract(discount)));
802	    46	    }
803	    47	
804	    48	    public static BigDecimal money(BigDecimal v) {
805	    49	        return v.setScale(2, RoundingMode.HALF_EVEN);
806	    50	    }
