     9	/** Pool de conexões, criação do esquema e transações. */
    10	public final class Database implements AutoCloseable {
    11	    private final HikariDataSource ds;
    12	
    13	    public interface Work<T> {
    14	        T run(Connection c) throws SQLException;
    15	    }
    16	
    17	    public Database(String url, String user, String password) {
    18	        HikariConfig hc = new HikariConfig();
    19	        hc.setJdbcUrl(url);
    20	        if (user != null) hc.setUsername(user);
    21	        if (password != null) hc.setPassword(password);
    22	        hc.setMaximumPoolSize(10);
    23	        hc.setInitializationFailTimeout(-1);
    24	        this.ds = new HikariDataSource(hc);
    25	    }
    26	
    27	    /** Cria o que falta no banco; espera o banco ficar disponível se preciso. */
    28	    public void migrate() {
    29	        SQLException last = null;
    30	        for (int attempt = 0; attempt < 30; attempt++) {
    31	            try {
    32	                tx(c -> {
    33	                    try (Statement s = c.createStatement()) {
    34	                        // evita corrida entre instâncias subindo juntas
    35	                        s.execute("SELECT pg_advisory_xact_lock(727001)");
    36	                        s.execute(SCHEMA);
    37	                        s.execute("""
    38	                                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    39	                                  (101, 'STANDARD', 2, 249.90), (102, 'STANDARD', 2, 249.90),
    40	                                  (201, 'DELUXE', 3, 389.90), (202, 'DELUXE', 3, 389.90),
    41	                                  (301, 'SUITE', 4, 579.90)
    42	                                ON CONFLICT (number) DO NOTHING""");
    43	                    }
    44	                    return null;
    45	                });
    46	                return;
    47	            } catch (SQLException e) {
    48	                last = e;
    49	                try {
    50	                    Thread.sleep(1000);
    51	                } catch (InterruptedException ie) {
    52	                    Thread.currentThread().interrupt();
    53	                    break;
    54	                }
    55	            }
    56	        }
    57	        throw new IllegalStateException("Não foi possível preparar o banco de dados", last);
    58	    }
    59	
    60	    public <T> T tx(Work<T> work) throws SQLException {
    61	        try (Connection c = ds.getConnection()) {
    62	            c.setAutoCommit(false);
    63	            try {
    64	                T result = work.run(c);
    65	                c.commit();
    66	                return result;
    67	            } catch (Throwable t) {
    68	                c.rollback();
    69	                throw t;
    70	            }
    71	        }
    72	    }
    73	
    74	    @Override
    75	    public void close() {
    76	        ds.close();
    77	    }
    78	
