     9	
    10	/** Cálculo de preço. Todo valor é arredondado a centavos (meio para o par) a cada passo. */
    11	public final class Pricing {
    12	    private Pricing() {}
    13	
    14	    private static final BigDecimal PEAK_FACTOR = new BigDecimal("1.20");
    15	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    16	
    17	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    18	
    19	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    20	    public static boolean isPeakSeason(LocalDate night) {
    21	        Month m = night.getMonth();
    22	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    23	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    24	    }
    25	
    26	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    27	        BigDecimal rate = room.nightlyRate();
    28	        if (isPeakSeason(night)) {
    29	            rate = rate.multiply(PEAK_FACTOR);
    30	        }
    31	        return money(rate);
    32	    }
    33	
    34	    /** As noites são as datas de checkIn (inclusive) a checkOut (exclusive). */
    35	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    36	        BigDecimal subtotal = BigDecimal.ZERO.setScale(2);
    37	        int nights = 0;
    38	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    39	            subtotal = subtotal.add(nightPrice(room, d));
    40	            nights++;
    41	        }
    42	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    43	                ? money(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    44	                : money(BigDecimal.ZERO);
    45	        return new Quote(nights, subtotal, discount, money(subtotal.subtract(discount)));
    46	    }
    47	
    48	    public static BigDecimal money(BigDecimal v) {
    49	        return v.setScale(2, RoundingMode.HALF_EVEN);
    50	    }
    51	}
