    23	    public String render() {
    24	        StringBuilder sb = new StringBuilder();
    25	        sb.append(TITLE).append(" nº ").append(reservationId).append('\n');
    26	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    27	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    28	        sb.append("Entrada: ").append(BR_DATE.format(checkIn))
    29	                .append(" | Saída: ").append(BR_DATE.format(checkOut))
    30	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    31	        sb.append("Diárias: ").append(brl(subtotal)).append('\n');
    32	        if (discount.signum() > 0) {
    33	            sb.append("Desconto: ").append(brl(discount)).append('\n');
    34	        }
    35	        sb.append("Total: ").append(brl(total));
    36	        return sb.toString();
    37	    }
    38	
    39	    /** 1234.56 -> "R$ 1.234,56" (sem depender do locale da JVM). */
    40	    public static String brl(BigDecimal v) {
    41	        String plain = Pricing.money(v).abs().toPlainString();
    42	        int dot = plain.indexOf('.');
    43	        String ints = plain.substring(0, dot);
    44	        StringBuilder grouped = new StringBuilder();
    45	        for (int i = 0; i < ints.length(); i++) {
    46	            if (i > 0 && (ints.length() - i) % 3 == 0) {
    47	                grouped.append('.');
    48	            }
    49	            grouped.append(ints.charAt(i));
    50	        }
    51	        return (v.signum() < 0 ? "-R$ " : "R$ ") + grouped + "," + plain.substring(dot + 1);
    52	    }
