   221	            Reservation r = load(c, id, false);
   222	            if (!r.status().isPaid()) {
   223	                throw ApiException.notAllowed("Só existe comprovante para reserva paga; situação atual: " + r.status());
   224	            }
   225	            return receipt(c, r);
   226	        });
   227	    }
   228	
   229	    private static Receipt receipt(Connection c, Reservation r) throws SQLException {
   230	        return Receipt.of(r, findRoom(c, r.roomNumber(), false).type());
   231	    }
   232	
   233	    // ---------- mensagens ----------
   234	
   235	    private void send(Connection c, Draft draft) throws SQLException {
   236	        ZonedDateTime now = ZonedDateTime.now(clock.withZone(config.zone()));
   237	        // serializa os envios para o mesmo hóspede, para o limite diário valer sob concorrência
   238	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(hashtext(?))")) {
   239	            ps.setString(1, Messaging.key(draft.to()));
   240	            ps.execute();
   241	        }
   242	        Messaging.Context ctx = new Messaging.Context(config.testMode(), now, addr -> {
   243	            try {
   244	                return countSentToday(c, addr, now);
   245	            } catch (SQLException e) {
   246	                throw new IllegalStateException(e);
   247	            }
   248	        });
   249	        for (Outgoing m : pipeline.process(draft, ctx)) {
   250	            try (PreparedStatement ps = c.prepareStatement("""
   251	                    INSERT INTO messages (channel, recipient, subject, body, status, guest_address, copy, created_at)
   252	                    VALUES (?,?,?,?,?,?,?,?)""")) {
   253	                ps.setString(1, m.channel().name());
   254	                ps.setString(2, m.to());
   255	                ps.setString(3, m.subject());
   256	                ps.setString(4, m.body());
   257	                ps.setString(5, m.status().name());
   258	                ps.setString(6, m.guestAddress());
   259	                ps.setBoolean(7, m.copy());
   260	                ps.setTimestamp(8, Timestamp.from(now.toInstant()));
   261	                ps.executeUpdate();
   262	            }
   263	        }
   264	    }
   265	
   266	    private static int countSentToday(Connection c, String address, ZonedDateTime now) throws SQLException {
   267	        ZonedDateTime start = now.toLocalDate().atStartOfDay(now.getZone());
   268	        try (PreparedStatement ps = c.prepareStatement("""
   269	                SELECT count(*) FROM messages
   270	                WHERE status = 'SENT' AND NOT copy AND lower(guest_address) = lower(?)
   271	                  AND created_at >= ? AND created_at < ?""")) {
   272	            ps.setString(1, address);
   273	            ps.setTimestamp(2, Timestamp.from(start.toInstant()));
   274	            ps.setTimestamp(3, Timestamp.from(start.plusDays(1).toInstant()));
   275	            try (ResultSet rs = ps.executeQuery()) {
   276	                rs.next();
   277	                return rs.getInt(1);
   278	            }
   279	        }
   280	    }
   281	
   282	    public List<StoredMessage> messages() {
   283	        return run(c -> {
   284	            List<StoredMessage> out = new ArrayList<>();
   285	            try (Statement s = c.createStatement();
   286	                 ResultSet rs = s.executeQuery("SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id")) {
   287	                while (rs.next()) {
   288	                    out.add(new StoredMessage(rs.getLong(1), rs.getString(2), rs.getString(3),
   289	                            rs.getString(4), rs.getString(5), rs.getString(6)));
   290	                }
   291	            }
   292	            return out;
   293	        });
   294	    }
   295	
   296	    // ---------- relatórios ----------
   297	
   298	    public String occupancyCsv(LocalDate night) {
   299	        return run(c -> {
   300	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
   301	            int occupied = 0;
   302	            try (PreparedStatement ps = c.prepareStatement("""
   303	                    SELECT r.room_number, m.type, r.id, r.check_in, r.check_out
   304	                    FROM reservations r JOIN rooms m ON m.number = r.room_number
   305	                    WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND r.check_in <= ? AND r.check_out > ?
   306	                    ORDER BY r.room_number, r.id""")) {
   307	                ps.setDate(1, Date.valueOf(night));
   308	                ps.setDate(2, Date.valueOf(night));
   309	                try (ResultSet rs = ps.executeQuery()) {
   310	                    while (rs.next()) {
   311	                        occupied++;
   312	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',')
   313	                                .append(rs.getLong(3)).append(',').append(rs.getDate(4).toLocalDate()).append(',')
   314	                                .append(rs.getDate(5).toLocalDate()).append('\n');
   315	                    }
   316	                }
   317	            }
   318	            int total;
   319	            try (Statement s = c.createStatement(); ResultSet rs = s.executeQuery("SELECT count(*) FROM rooms")) {
   320	                rs.next();
   321	                total = rs.getInt(1);
   322	            }
   323	            return sb.append("total,").append(occupied).append('/').append(total).append('\n').toString();
   324	        });
   325	    }
   326	
   327	    public String revenueCsv(YearMonth month) {
   328	        return run(c -> {
   329	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   330	            BigDecimal sum = BigDecimal.ZERO.setScale(2);
   331	            try (PreparedStatement ps = c.prepareStatement("""
   332	                    SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0) AS amount
   333	                    FROM reservations
   334	                    WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0
   335	                    ORDER BY check_in, id""")) {
   336	                ps.setDate(1, Date.valueOf(month.atDay(1)));
   337	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
   338	                try (ResultSet rs = ps.executeQuery()) {
   339	                    while (rs.next()) {
   340	                        BigDecimal amount = rs.getBigDecimal("amount").setScale(2);
   341	                        sum = sum.add(amount);
   342	                        sb.append(rs.getLong("id")).append(',').append(rs.getInt("room_number")).append(',')
   343	                                .append(rs.getDate("check_in").toLocalDate()).append(',')
   344	                                .append(rs.getDate("check_out").toLocalDate()).append(',')
   345	                                .append(rs.getString("status")).append(',').append(amount.toPlainString()).append('\n');
   346	                    }
   347	                }
   348	            }
   349	            return sb.append("total,").append(sum.toPlainString()).append('\n').toString();
   350	        });
   351	    }
   352	}

