251	    static Res call(Env e, String method, String path, String body) throws Exception {
252	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(e.base + path));
253	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
254	        HttpResponse<String> r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
255	        return new Res(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
256	    }
